<script setup>
import { computed, onMounted, ref } from "vue";

const API = "/api";
const parentToken = ref(localStorage.getItem("sp_parent_jwt") || "");
const authMode = ref("pin");
const pin = ref("");
const showLogin = ref(false);
const loading = ref(true);
const error = ref("");
const notice = ref("");
const view = ref("home");
const adminTab = ref("overview");
const students = ref([]);
const currentStudent = ref(Number(localStorage.getItem("sp_stu") || 0));
const points = ref(0);
const sessions = ref([]);
const subjects = ref([]);
const tasks = ref([]), rewards = ref([]), logs = ref([]);
const lesson = ref(null), questions = ref([]), questionIndex = ref(0), combo = ref(0), sessionId = ref(null), result = ref(null);
const fx = ref(""), leaderboard = ref(null), wrongCount = ref(0), showBoard = ref(false);
const newTask = ref({ title: "", type: "学习", due_date: "", points: 5 });
const newReward = ref({ name: "", cost_points: 20 });
const newStudent = ref({ name: "", username: "", avatar: "🐣", grade: 1 });
const showAddStudent = ref(false);
const gradeOptions = [
  { value: 1, label: "一年级" },
  { value: 2, label: "二年级" },
  { value: 3, label: "三年级" },
  { value: 4, label: "四年级" },
  { value: 5, label: "五年级" },
  { value: 6, label: "六年级" },
  { value: 7, label: "初一" },
  { value: 8, label: "初二" },
  { value: 9, label: "初三" }
];
const avatarOptions = ["🐣", "🚀", "🌟", "🦊", "🐼", "🦄", "🐬", "🐨"];
function openAddStudent() { newStudent.value = { name: "", username: "", avatar: "🐣", grade: 1 }; showAddStudent.value = true; }
const newPin = ref("");
const isParent = computed(() => !!parentToken.value);
const hasStudent = computed(() => students.value.length > 0 && !!currentStudent.value);
const activeStudent = computed(() => students.value.find(s => s.id === currentStudent.value));
const activeQuestion = computed(() => questions.value[questionIndex.value]);
const progress = computed(() => questions.value.length ? Math.round((questionIndex.value / questions.value.length) * 100) : 0);
// 学习地图：学科从接口动态获取（内容库驱动，新增学科无需改前端）
const unitColors = ["word", "read", "math", "sci", "sci2", "bio", "his", "geo"];
const fallbackUnits = [
  { code: "english", name: "英语", icon: "Aa", count: 0 },
  { code: "chinese", name: "语文", icon: "文", count: 0 },
  { code: "math", name: "数学", icon: "∑", count: 0 }
];
const units = computed(() => {
  const g = activeStudent.value?.grade || 0;
  // 只显示该学段开设的学科（后端 subjects 带 min/max_grade，这里再兜底过滤）
  const list = (subjects.value.length ? subjects.value : fallbackUnits).filter(s => !g || !s.min_grade || (g >= s.min_grade && g <= s.max_grade));
  return list.map((s, i) => ({ kind: s.code, title: s.name, sub: `${s.count || 0} 道题 · ${gradeLabel(activeStudent.value?.grade)}`, className: unitColors[i % unitColors.length], icon: s.icon || s.name[0] }));
});
function gradeLabel(g) { const opt = gradeOptions.find(x => x.value === (g || 1)); return opt ? opt.label : `${g || 1}年级`; }
function wrongSubject() { const order = ["math", "english", "chinese", "physics", "chemistry", "biology", "history", "geography"]; for (const s of order) { const u = subjects.value.find(x => x.code === s); if (u && u.count > 0) return s; } return "math"; }
function api(path, options = {}) { const sep = path.includes("?") ? "&" : "?"; const headers = { "Content-Type": "application/json", ...(options.headers || {}) }; if (parentToken.value) headers.Authorization = `Bearer ${parentToken.value}`; return fetch(`${API}${path}${options.child === false ? "" : `${sep}student_id=${currentStudent.value}`}`, { ...options, headers, body: options.body ? JSON.stringify(options.body) : undefined }).then(async r => { const data = await r.json().catch(() => null); if (r.status === 401 && parentToken.value) { parentToken.value = ""; localStorage.removeItem("sp_parent_jwt"); students.value = []; currentStudent.value = 0; view.value = "home"; } if (!r.ok) throw new Error(data?.error || `请求失败（${r.status}）`); return data; }); }
function fail(e) { error.value = e.message || String(e); }
function shuffle(a) { return [...a].sort(() => Math.random() - .5); }
function starCount(u) { return sessions.value.filter(x => x.subject === u.kind && x.level === 1).reduce((b, x) => Math.max(b, x.stars || 0), 0); }
function totalStars() { return sessions.value.reduce((s, x) => s + (x.stars || 0), 0); }
function maxCombo() { return sessions.value.reduce((b, x) => Math.max(b, x.max_combo || 0), 0); }
function playFx(kind) { fx.value = kind; setTimeout(() => { if (fx.value === kind) fx.value = ""; }, kind === "star" ? 1600 : 900); }
async function loadWrong() { try { const w = await api("/wrong-questions"); wrongCount.value = (w || []).filter(x => !Number(x.resolved)).length; } catch { wrongCount.value = 0; } }
async function loadLeaderboard() { try { leaderboard.value = await api("/leaderboard/weekly?limit=20"); } catch { leaderboard.value = null; } }
async function showLeaderboard() { await loadLeaderboard(); leaderboard.value = leaderboard.value || { entries: [] }; showBoard.value = true; }
async function load() { if (!isParent.value) return; loading.value = true; try { const ss = await api("/students", { child: false }); students.value = ss || []; if (!students.value.some(s => s.id === currentStudent.value)) currentStudent.value = students.value[0]?.id || 0; try { subjects.value = await api(`/subjects?grade=${activeStudent.value?.grade || 0}`, { child: false }); } catch { subjects.value = []; } if (hasStudent.value) { const [pp, se] = await Promise.all([api("/points"), api("/sessions")]); points.value = pp?.total || 0; sessions.value = se || []; } } catch (e) { fail(e); } finally { loading.value = false; } }
async function switchStudent(id) { currentStudent.value = id; localStorage.setItem("sp_stu", String(id)); view.value = "home"; await load(); await loadWrong(); }
// 内容库出题：抽题（不含答案）→ 混入错题 → 创建场次
async function startUnit(unit) { if (!hasStudent.value) { adminTab.value = "students"; view.value = "admin"; return; } try { const picked = await api(`/content/pick?subject=${unit.kind}&grade=${activeStudent.value?.grade || 1}&limit=5`) || []; if (!picked.length) throw new Error(`「${unit.title}」的题库还是空的，等待资料导入`); let list = picked.map(q => ({ id: q.id, type: "content", subject: q.subject, title: q.question, passage: q.passage || "", subtitle: q.topic || "", options: shuffle(q.options || []), review: false })); list = await mixWrongQuestions(unit.kind, list); if (!list.length) throw new Error("这一关还没有题目"); const s = await api("/sessions", { method: "POST", body: { subject: unit.kind, level: activeStudent.value?.grade || 1, total: list.length } }); lesson.value = unit; questions.value = list; questionIndex.value = 0; combo.value = 0; sessionId.value = s.id; result.value = null; view.value = "lesson"; } catch (e) { fail(e); } }
// 错题巩固：内容库题目通过 /content/item 回取（服务端判分，前端无答案）
async function mixWrongQuestions(kind, list) { try { const wrongs = await api(`/wrong-questions?subject=${kind}`) || []; const wrongIds = wrongs.filter(w => !Number(w.resolved)).slice(0, 3).map(w => Number(w.ref_id)); const idSet = new Set(list.map(q => q.id)); const reviewQs = []; for (const wid of wrongIds) { if (idSet.has(wid)) continue; try { const q = await api(`/content/item?id=${wid}`); reviewQs.push({ id: q.id, type: "content", subject: q.subject, title: q.question, passage: q.passage || "", subtitle: q.topic || "", options: shuffle(q.options || []), review: true }); } catch {} } const mixed = []; let wi = 0; list.forEach((q, i) => { mixed.push(q); if ((i + 1) % 2 === 0 && wi < reviewQs.length) mixed.push(reviewQs[wi++]); }); while (wi < reviewQs.length) mixed.push(reviewQs[wi++]); return mixed; } catch { return list; } }
async function selectOption(o) { const q = activeQuestion.value; if (!q || q.picked !== undefined) return; q.picked = o; try { const r = await api("/content/answer", { method: "POST", body: { id: q.id, answer: o, session_id: sessionId.value } }); q.correct = r.correct ?? false; q.rightAnswer = r.answer || ""; combo.value = q.correct ? (r.combo || combo.value + 1) : 0; if (q.correct) { q.xp = r.xp || 0; playFx(combo.value >= 3 ? "combo" : "right"); } else { playFx("wrong"); } } catch (e) { fail(e); } }
async function nextQuestion() { if (questionIndex.value + 1 < questions.value.length) { questionIndex.value++; return; } try { result.value = await api(`/sessions/${sessionId.value}/finish`, { method: "POST" }); if (result.value?.stars >= 2) playFx("star"); await load(); await loadWrong(); } catch (e) { fail(e); } }
function backHome() { result.value = null; view.value = "home"; }
async function loadAuth() { try { authMode.value = (await api("/parent/auth-mode", { child: false })).mode || "pin"; } catch {} }
async function login() { try { const r = await api("/parent/login", { method: "POST", child: false, body: { pin: pin.value } }); parentToken.value = r.token; localStorage.setItem("sp_parent_jwt", r.token); showLogin.value = false; pin.value = ""; await load(); if (!hasStudent.value) { view.value = "admin"; adminTab.value = "students"; } } catch (e) { fail(e); } }
function logout() { parentToken.value = ""; localStorage.removeItem("sp_parent_jwt"); students.value = []; currentStudent.value = 0; view.value = "home"; showLogin.value = false; }
async function enterAdmin(tab = "overview") { if (!isParent.value) { showLogin.value = true; return; } adminTab.value = tab; view.value = "admin"; await loadAdmin(); }
async function loadAdmin() { if (!isParent.value) return; try { const [tt, rr, ll] = await Promise.all([api(`/tasks?student_id=${currentStudent.value}`, { child: false }), api("/rewards", { child: false }), api(`/points/log?student_id=${currentStudent.value}`, { child: false })]); tasks.value = tt || []; rewards.value = rr || []; logs.value = ll || []; } catch (e) { fail(e); } }
async function addTask() { try { await api("/parent/tasks", { method: "POST", child: false, body: { ...newTask.value, student_id: currentStudent.value } }); newTask.value = { title: "", type: "学习", due_date: "", points: 5 }; notice.value = "任务已发布"; await loadAdmin(); } catch (e) { fail(e); } }
async function addReward() { try { await api("/parent/rewards", { method: "POST", child: false, body: newReward.value }); newReward.value = { name: "", cost_points: 20 }; notice.value = "奖励已添加"; await loadAdmin(); } catch (e) { fail(e); } }
async function addStudent() { if (!newStudent.value.name.trim()) { error.value = "请先填写孩子姓名"; return; } try { await api("/parent/students", { method: "POST", child: false, body: newStudent.value }); showAddStudent.value = false; newStudent.value = { name: "", username: "", avatar: "🐣", grade: 1 }; notice.value = "孩子账号已创建，可以在底部「学习」页切换到 TA 的学习工作台"; await load(); await loadAdmin(); } catch (e) { fail(e); } }
async function deleteStudent(id) { if (!confirm("确定删除这个学生及其学习数据吗？")) return; try { await api(`/parent/students/${id}`, { method: "DELETE", child: false }); await load(); await loadAdmin(); } catch (e) { fail(e); } }
async function deleteTask(id) { try { await api(`/parent/tasks/${id}`, { method: "DELETE", child: false }); await loadAdmin(); } catch (e) { fail(e); } }
async function savePin() { try { await api("/parent/set-pin", { method: "POST", child: false, body: { pin: newPin.value } }); newPin.value = ""; notice.value = "PIN 已更新"; } catch (e) { fail(e); } }
onMounted(async () => { await loadAuth(); if (isParent.value) { await load(); await loadWrong(); } else loading.value = false; });
</script>

<template>
  <main class="shell">
    <header class="topbar"><div class="brand"><div class="logo"><img src="/logo.png" alt="学霸星球" /></div><div><p class="eyebrow">STUDY PLANET · 学习成长空间</p><h1>学霸星球</h1><p>{{ isParent ? (view === 'admin' ? '家长管理中心' : '今天也要向前一点点') : '专为孩子设计的学习旅程' }}</p></div></div><div class="top-actions"><div v-if="hasStudent" class="xp-ring"><strong>{{ points }}</strong><span>积分</span></div><button v-if="isParent" class="parent-entry" @click="enterAdmin()">家长中心</button></div></header>
    <section v-if="!isParent" class="welcome card"><div class="welcome-art"><div class="planet">学</div><span class="orbit orbit-a"></span><span class="orbit orbit-b"></span></div><div class="welcome-copy"><p class="eyebrow orange">家长先登录，开启学习旅程</p><h2>先管理家庭成员<br />再让孩子开始学习</h2><p>家长登录后，可以创建孩子账号、安排每日任务、设置奖励，并查看学习成长记录。</p><button class="cta" @click="showLogin=true">进入家长登录 <span>→</span></button></div><div class="feature-strip"><span>✦ 安全的家庭空间</span><span>✦ 趣味化闯关学习</span><span>✦ 可追踪成长记录</span></div></section>
    <section v-else-if="loading" class="card loading">正在装载学习星球…</section>
    <section v-else-if="view === 'home'" class="home">
      <div v-if="!hasStudent" class="empty-state card"><div class="empty-icon">👨‍👩‍👧‍👦</div><p class="eyebrow orange">第一步 · 创建学习账号</p><h2>还没有学生账号</h2><p>请先在家长中心添加孩子，完成后这里就会出现专属学习工作台。</p><button class="cta" @click="enterAdmin('students')">去添加学生 <span>→</span></button></div>
      <template v-else><section class="dashboard-hero"><div><p class="eyebrow orange">{{ activeStudent?.name }}的学习星球</p><h2>今天想去哪里探索？</h2><p>每一次练习，都会变成成长路上的一颗星。</p></div><div class="hero-badge">{{ activeStudent?.avatar || '🐣' }}<small>Lv.{{ activeStudent?.level || 1 }}</small></div></section><div class="student-switcher"><span class="section-label">当前学习者</span><button v-for="s in students" :key="s.id" class="student" :class="{ active: s.id === currentStudent }" @click="switchStudent(s.id)"><span>{{ s.avatar || '🐣' }}</span>{{ s.name }}<b v-if="s.id === currentStudent">✓</b></button><button class="add-child" @click="enterAdmin('students')">＋ 添加孩子</button></div><section class="path card"><div class="section-heading"><div><p class="eyebrow">LEARNING MAP</p><h2>学习探索地图</h2></div><span class="map-progress">{{ totalStars() }} 颗星星</span></div><div class="units"><button v-for="u in units" :key="u.kind" class="unit" :class="u.className" @click="startUnit(u)"><span class="unit-icon">{{ u.icon }}</span><span class="stars">{{ '★'.repeat(starCount(u)) }}<i>{{ '☆'.repeat(3 - starCount(u)) }}</i></span><strong>{{ u.title }}</strong><small>{{ u.sub }}</small><em>开始探索 <b>→</b></em></button></div></section><div class="quick-grid"><button @click="enterAdmin('tasks')"><span class="quick-icon">✓</span><span><b>今日任务</b><small>{{ tasks.filter(t => t.status !== 'done').length || '查看任务安排' }}</small></span><i>→</i></button><button @click="enterAdmin('rewards')"><span class="quick-icon gift">◆</span><span><b>奖励商店</b><small>完成目标兑换奖励</small></span><i>→</i></button><button @click="showLeaderboard"><span class="quick-icon rank">♛</span><span><b>本周排行榜</b><small>比一比谁的经验多</small></span><i>→</i></button></div><section v-if="wrongCount" class="wrong-card card" @click="startUnit({ kind: wrongSubject(), title: '错题巩固' })"><div class="wrong-icon">📕</div><div class="wrong-copy"><b>错题本有 {{ wrongCount }} 道题待巩固</b><small>练习时会自动穿插错题，答对即可消除</small></div><i>→</i></section><section class="growth card"><div class="pet-zone"><div class="bubble">准备好闯关了吗？</div><div class="pet">🌟</div></div><div class="stats"><div><b>{{ points }}</b><span>我的积分</span></div><div><b>{{ maxCombo() }}</b><span>最高连击</span></div><div><b>{{ totalStars() }}</b><span>收集星星</span></div></div></section></template>
    </section>
    <section v-else-if="view === 'lesson'" class="lesson"><div class="lesson-top"><button class="close" @click="view='home'">×</button><div class="progress"><i :style="{ width: `${progress}%` }" /></div><b v-if="combo >= 2">连击 x{{ combo }}</b></div><article v-if="activeQuestion" class="card question" :class="{ 'review-q': activeQuestion.review }"><p class="eyebrow orange">{{ activeQuestion.subject === 'english' ? '英语挑战' : activeQuestion.subject === 'chinese' ? '语文挑战' : activeQuestion.subject === 'math' ? '数学挑战' : activeQuestion.subject === 'physics' ? '物理挑战' : activeQuestion.subject === 'chemistry' ? '化学挑战' : activeQuestion.subject === 'biology' ? '生物挑战' : activeQuestion.subject === 'history' ? '历史挑战' : '地理挑战' }} <span v-if="activeQuestion.review" class="review-tag">错题巩固</span></p><h2>{{ activeQuestion.title }}</h2><p v-if="activeQuestion.passage" class="passage">{{ activeQuestion.passage }}</p><em>{{ activeQuestion.subtitle }}</em><div class="options"><button v-for="o in activeQuestion.options" :key="o" :disabled="activeQuestion.picked !== undefined" :class="{ right: activeQuestion.picked !== undefined && o === activeQuestion.rightAnswer, wrong: activeQuestion.picked === o && !activeQuestion.correct }" @click="selectOption(o)">{{ o }}</button></div><button v-if="activeQuestion.picked !== undefined" class="cta continue" @click="nextQuestion">{{ questionIndex + 1 < questions.length ? '继续下一题 →' : '完成关卡 ✓' }}</button></article><div v-if="fx" class="fx-layer"><template v-if="fx==='right'"><span class="fx-pop">+{{ activeQuestion?.xp || 0 }} XP</span></template><template v-else-if="fx==='combo'"><span class="fx-combo">🔥 连击 x{{ combo }}！<small>+{{ activeQuestion?.xp || 0 }} XP</small></span></template><template v-else-if="fx==='wrong'"><span class="fx-wrong">💪 再想想，已加入错题本</span></template><template v-else-if="fx==='star'"><span class="fx-stars">★★★</span></template></div></section>
    <section v-else class="admin card"><nav class="admin-nav"><button :class="{active:adminTab==='overview'}" @click="adminTab='overview'">总览</button><button :class="{active:adminTab==='students'}" @click="adminTab='students'">孩子管理</button><button :class="{active:adminTab==='tasks'}" @click="adminTab='tasks'">学习任务</button><button :class="{active:adminTab==='rewards'}" @click="adminTab='rewards'">奖励商店</button><button :class="{active:adminTab==='logs'}" @click="adminTab='logs'">成长记录</button><button :class="{active:adminTab==='settings'}" @click="adminTab='settings'">账户设置</button></nav><div class="admin-head"><div><p class="eyebrow orange">PARENT SPACE</p><h2>家长管理中心</h2></div><div><button class="back-link" @click="view='home'">返回学习工作台</button><button class="danger-link" @click="logout">退出登录</button></div></div><div v-if="adminTab==='overview'" class="panel"><p class="muted">管理孩子的学习任务、奖励和成长记录。</p><div class="overview-grid"><div><b>{{ students.length }}</b><span>孩子账号</span></div><div><b>{{ tasks.filter(t=>t.status!=='done').length }}</b><span>待完成任务</span></div><div><b>{{ rewards.length }}</b><span>奖励项目</span></div><div><b>{{ points }}</b><span>当前积分</span></div></div><div class="admin-tip">💡 先添加孩子，再从学习工作台切换学习者；每个孩子的学习进度和积分独立保存。</div></div><div v-if="adminTab==='students'" class="panel"><h3>孩子账号</h3><p class="muted">创建后，孩子才能进入专属学习工作台。</p><button class="primary add-student-btn" @click="openAddStudent">＋ 添加孩子账号</button><div class="list"><div v-for="s in students" :key="s.id" class="list-row"><span class="avatar">{{ s.avatar || '🐣' }}</span><strong>{{ s.name }}</strong><small>{{ s.grade || 5 }}年级 · {{ s.username || '未设置用户名' }}</small><button class="select-link" @click="switchStudent(s.id)">{{ s.id === currentStudent ? '当前学习者' : '切换' }}</button><button class="danger-link" @click="deleteStudent(s.id)">删除</button></div><div v-if="!students.length" class="empty">还没有孩子账号，请先创建一个。</div></div></div><div v-if="adminTab==='tasks'" class="panel"><h3>学习任务</h3><div class="form-row"><input v-model="newTask.title" placeholder="任务名称，如：朗读课文" /><input v-model="newTask.due_date" type="date" /><input v-model.number="newTask.points" type="number" placeholder="奖励积分" /><button class="primary" @click="addTask">发布任务</button></div><div class="list"><div v-for="t in tasks" :key="t.id" class="list-row"><span class="task-check">✓</span><strong>{{ t.title }}</strong><small>+{{ t.points }} 积分 · {{ t.due_date || '今天' }}</small><button class="danger-link" @click="deleteTask(t.id)">删除</button></div><div v-if="!tasks.length" class="empty">还没有任务安排。</div></div></div><div v-if="adminTab==='rewards'" class="panel"><h3>奖励商店</h3><div class="form-row"><input v-model="newReward.name" placeholder="奖励名称，如：看一集动画片" /><input v-model.number="newReward.cost_points" type="number" placeholder="所需积分" /><button class="primary" @click="addReward">添加奖励</button></div><div class="reward-grid"><div v-for="r in rewards" :key="r.id" class="reward"><span class="reward-icon">◆</span><strong>{{ r.name }}</strong><b>{{ r.cost_points }} 积分</b></div><div v-if="!rewards.length" class="empty">还没有奖励项目。</div></div></div><div v-if="adminTab==='logs'" class="panel"><h3>成长记录</h3><div class="list"><div v-for="l in logs" :key="l.id" class="list-row"><span :class="l.delta > 0 ? 'gain' : 'loss'">{{ l.delta > 0 ? '+' : '' }}{{ l.delta }}</span><strong>{{ l.reason }}</strong><small>{{ l.created_at }}</small></div><div v-if="!logs.length" class="empty">完成学习后，这里会留下成长记录。</div></div></div><div v-if="adminTab==='settings'" class="panel"><h3>账户设置</h3><p class="muted">修改家长 PIN，保护家庭学习数据。</p><div class="form-row"><input v-model="newPin" type="password" placeholder="输入新的家长 PIN" /><button class="primary" @click="savePin">保存 PIN</button></div></div></section>
    <nav v-if="isParent && view !== 'lesson'" class="bottom-menu" aria-label="主菜单"><button :class="{ active: view === 'home' }" @click="view = 'home'"><span class="menu-icon">⌂</span><span>学习</span></button><button :class="{ active: view === 'admin' && adminTab === 'tasks' }" @click="enterAdmin('tasks')"><span class="menu-icon">✓</span><span>任务</span></button><button :class="{ active: view === 'admin' && adminTab === 'rewards' }" @click="enterAdmin('rewards')"><span class="menu-icon">★</span><span>奖励</span></button><button :class="{ active: view === 'admin' && ['overview', 'students', 'logs', 'settings'].includes(adminTab) }" @click="enterAdmin('overview')"><span class="menu-icon">♙</span><span>家长</span></button></nav>
    <div v-if="result" class="modal"><section class="result card"><div class="result-star">★</div><p class="eyebrow orange">MISSION COMPLETE</p><h2>闯关完成！</h2><p>答对 {{ result.correct }}/{{ result.total }} 题 · 最高连击 x{{ result.max_combo }}</p><div class="result-stars">{{ '★'.repeat(result.stars || 0) }}<i>{{ '☆'.repeat(3 - (result.stars || 0)) }}</i></div><div v-if="result.xp_gained" class="result-xp">✨ 经验值 +{{ result.xp_gained }}</div><button class="cta" @click="backHome">回到学习地图</button></section></div>
        <div v-if="showBoard" class="modal" @click.self="showBoard=false"><section class="dialog card board-dialog"><button class="close" @click="showBoard=false">×</button><p class="eyebrow orange">WEEKLY RANKING</p><h2>本周经验排行榜</h2><p class="muted">{{ leaderboard?.week }} 周 · 按本周获得的经验值排名</p><ol class="board-list"><li v-for="(e, i) in leaderboard?.entries || []" :key="e.child_id" :class="{ me: e.child_id === currentStudent, top3: i < 3 }"><span class="board-rank">{{ ['🥇','🥈','🥉'][i] || e.rank }}</span><span class="board-avatar">{{ e.avatar || '🐣' }}</span><span class="board-name">{{ e.name }}</span><b class="board-xp">{{ e.xp }} XP</b></li><li v-if="!(leaderboard?.entries || []).length" class="board-empty">本周还没有人上榜，快去闯关赚经验吧！</li></ol><div v-if="leaderboard?.my_xp" class="board-mine">我的本周经验：<b>{{ leaderboard.my_xp }} XP</b></div></section></div><div v-if="showAddStudent" class="modal" @click.self="showAddStudent=false"><section class="dialog card add-student-dialog"><button class="close" @click="showAddStudent=false">×</button><p class="eyebrow orange">NEW LEARNER</p><h2>添加孩子账号</h2><p class="muted">填写孩子的基础信息，创建后即可切换到 TA 的专属学习工作台。</p><div class="field"><label>孩子姓名 <b>*</b></label><input v-model="newStudent.name" placeholder="例如：小明" /><small>将显示在孩子的学习工作台上，必填。</small></div><div class="field"><label>用户名（可选）</label><input v-model="newStudent.username" placeholder="例如：xiaoming" /><small>用于孩子登录学习端，留空则不启用用户名登录。</small></div><div class="field"><label>头像</label><div class="avatar-pick"><button v-for="a in avatarOptions" :key="a" type="button" :class="{ picked: newStudent.avatar === a }" @click="newStudent.avatar=a">{{ a }}</button></div><small>给孩子选一个喜欢的形象，会出现在学习地图和排行榜。</small></div><div class="field"><label>年级</label><select v-model.number="newStudent.grade"><option v-for="g in gradeOptions" :key="g.value" :value="g.value">{{ g.label }}</option></select><small>决定学习内容的难度，之后可在孩子管理中调整。</small></div><button class="cta full" @click="addStudent">创建孩子账号</button></section></div><div v-if="showLogin" class="modal"><section class="dialog card"><button class="close" @click="showLogin=false">×</button><div class="login-mark">🔐</div><p class="eyebrow orange">PARENT ACCESS</p><h2>家长登录</h2><p v-if="authMode==='casdoor'">使用 Casdoor 账号安全登录</p><a v-if="authMode==='casdoor'" class="primary button-link" href="/api/parent/casdoor/login">前往登录</a><template v-else><p class="muted">登录后才能添加孩子和管理学习空间</p><input v-model="pin" type="password" placeholder="请输入家长 PIN" @keyup.enter="login" /><button class="cta full" @click="login">登录并进入管理中心</button></template></section></div><div v-if="error" class="modal"><section class="dialog card"><h2>操作未完成</h2><p>{{ error }}</p><button class="primary" @click="error=''">知道了</button></section></div><div v-if="notice" class="modal"><section class="dialog card"><div class="success-mark">✓</div><h2>操作成功</h2><p>{{ notice }}</p><button class="primary" @click="notice=''">好的</button></section></div>
  </main>
</template>
